const C = require('crypto-js');
test("progressive", () => {
  expect(C.algo.SHA256.create().update("a").update("bc").finalize().toString()).to.equal(C.SHA256("abc").toString());
  expect(C.algo.HMAC.create(C.algo.SHA256, "key").update("The quick brown fox ").update("jumps over the lazy dog").finalize().toString())
    .to.equal("f7bc83f430538424b13298e6aa6fb143ef4d59a14946175997479dbc2d1a3cd8");
});
test("pbkdf2 (RFC 6070)", () => {
  expect(C.PBKDF2("password", "salt", { keySize: 5, iterations: 2, hasher: C.algo.SHA1 }).toString()).to.equal("ea6c014dc72d6f8ccd1ed92ace1d41f0d8de8957");
});
